PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?rt .
  FILTER(LCASE(STR(?rt)) = "aggressive") .

  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:riskScore ?riskScore .
  FILTER(?riskScore > 75) .

  FILTER EXISTS {
    ?phold a wm:PortfolioHolding ;
           wm:investorId ?investorId ;
           wm:investmentType ?invType .
    FILTER(LCASE(STR(?invType)) = "global equity") .
  }
}

