PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorLabel
WHERE {
  ?inv a wm:Investor ;
       rdfs:label ?investorLabel ;
       wm:riskTolerance ?rt ;
       wm:investorId ?investorId .
  FILTER(LCASE(?rt) = "conservative")

  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:liquidityScore ?liq .
  FILTER(?liq < 50)

  ?sa a wm:SectorAllocation ;
       wm:investorId ?investorId ;
       wm:sector ?sector ;
       wm:allocationPct ?alloc .
  FILTER(LCASE(?sector) = "consumer goods")
  FILTER(?alloc > 0)
