PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ( ?investorId AS ?investor_id )
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .

  FILTER EXISTS {
    ?inv wm:hasScenarioRebalancing ?sr .
    ?sr wm:hasMarketScenario ?ms .
    ?ms rdfs:label "Bull Market" .
  }

  FILTER EXISTS {
    ?goal wm:belongsToInvestor ?inv ;
          wm:shortfall ?sf .
    FILTER ( ?sf > 0 )
  }
}

