PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskTolerance ?diversificationScore ?scenario ?shortfall
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTolerance .
  FILTER(LCASE(?riskTolerance) = "moderate")

  {
    SELECT ?investorId (MIN(?divScore) AS ?diversificationScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:diversificationScore ?divScore .
      FILTER(?divScore < 25)
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (SAMPLE(?sc) AS ?scenario)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:scenario ?sc .
      FILTER(LCASE(?sc) = "bear market")
    }
    GROUP BY ?investorId
  }

  {
    SELECT ?investorId (MIN(?sf) AS ?shortfall)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:shortfall ?sf .
      FILTER(?sf > 0)
    }
    GROUP BY ?investorId
  }
}

