PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?portfolioHealthId ?label
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:portfolioHealthId ?portfolioHealthId ;
      rdfs:label ?label ;
      wm:liquidityScore ?liq ;
      wm:diversificationScore ?div .
  FILTER(?liq < 25 && ?div < 25)
}

