Generated SPARQL:
SELECT "goal_id" AS "goal_id", "investment_goal" AS "investment_goal"
FROM "ATOM_ENTITY_INVESTMENT_GOAL_001"
WHERE "shortfall" > 0;

SELECT "goal_id" AS "goal_id", "investment_goal" AS "investment_goal", "progress_pct" AS "progress_pct"
FROM "ATOM_ENTITY_INVESTMENT_GOAL_001"
WHERE "progress_pct" < 50;

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?label
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:riskTolerance ?rt ;
            rdfs:label ?label .
  FILTER (LCASE(?rt) = "aggressive")

  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:riskScore ?riskScore .
  FILTER (xsd:decimal(?riskScore) > 90)
}

