Generated SPARQL:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?investorId ?investorName ?riskScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol .
  FILTER(LCASE(?riskTol) = "conservative") .

  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:riskScore ?riskScore .
  FILTER(?riskScore > 90)
}

