PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?loss_holding_count WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance "Conservative" .

  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:diversificationScore ?divScore .
  FILTER(?divScore < 25) .

  {
    SELECT ?investorId (COUNT(?holding) AS ?loss_holding_count) WHERE {
      ?inv2 a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasHolding ?holding .
      ?holding wm:cost ?cost ;
               wm:currentValue ?curr .
      FILTER(bound(?cost) && bound(?curr) && ?curr < ?cost)
    } GROUP BY ?investorId
  }

  FILTER(?loss_holding_count > 0)
}

