Generated SPARQL:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
           wm:investorId ?investorId ;
           wm:investorName ?investorName ;
           wm:segment ?segment ;
           wm:hasPortfolioHealth ?ph ;
           wm:hasHolding ?holding .

  FILTER(LCASE(STR(?segment)) = "diversified") .

  ?ph wm:liquidityScore ?liqScore .
  FILTER(xsd:decimal(?liqScore) < 50) .

  ?holding wm:investmentType ?invType .
  FILTER(LCASE(STR(?invType)) = "corporate bond") .
}
GROUP BY ?investorId ?investorName

